function uploadHeroBackground(input) {
    if (input.files && input.files[0]) {
        const file = input.files[0];
        const formData = new FormData();
        formData.append('background_image', file);
        formData.append('_token', window.csrfToken || document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '');

        axios.post('/api/site-config/hero', formData, {
            headers: {
                'Content-Type': 'multipart/form-data'
            }
        })
        .then(response => {
            if (response.data.success) {
                document.querySelector('#beranda').style.backgroundImage = `url('/${response.data.path}')`;
                Swal.fire({
                    icon: 'success',
                    title: 'Berhasil',
                    text: response.data.message,
                    timer: 2000,
                    showConfirmButton: false
                });
            }
        })
        .catch(error => {
            Swal.fire({
                icon: 'error',
                title: 'Error',
                text: error.response?.data?.error || 'Gagal mengupload background'
            });
        })
        .finally(() => {
            input.value = '';
        });
    }
}

function editHeroBadge() {
    const currentText = document.getElementById('hero-badge-text')?.textContent.trim() || 'Periode 2026';

    if (typeof Swal === 'undefined') {
        const newBadge = prompt('Masukkan Periode OSIS baru:', currentText);
        if (newBadge !== null && newBadge.trim()) {
            saveHeroConfig({ badge: newBadge.trim() }, () => {
                const el = document.getElementById('hero-badge-text');
                if (el) el.textContent = newBadge.trim();
            });
        }
        return;
    }

    Swal.fire({
        title: '<span style="color:#0f172a; font-weight:800; font-size:1.25rem;">Ubah Periode OSIS</span>',
        html: '<p style="color:#64748b; font-size:0.875rem; margin-bottom:1rem;">Teks ini akan tampil pada lencana di bagian atas halaman Beranda.</p>',
        input: 'text',
        inputValue: currentText,
        inputPlaceholder: 'Contoh: Periode 2026 / 2026 - 2027',
        showCancelButton: true,
        confirmButtonText: 'Simpan Perubahan',
        cancelButtonText: 'Batal',
        confirmButtonColor: '#e11d48',
        cancelButtonColor: '#94a3b8',
        customClass: {
            popup: 'rounded-3xl border border-slate-100 shadow-2xl p-6',
            input: 'rounded-xl border border-slate-200 text-slate-800 text-sm font-semibold p-3',
            confirmButton: 'rounded-xl font-bold px-5 py-2.5 shadow-md shadow-rose-200',
            cancelButton: 'rounded-xl font-semibold px-4 py-2.5'
        },
        inputValidator: (value) => {
            if (!value || !value.trim()) {
                return 'Periode tidak boleh kosong!';
            }
        }
    }).then((result) => {
        if (result.isConfirmed) {
            const newBadge = result.value.trim();
            saveHeroConfig({ badge: newBadge }, () => {
                const el = document.getElementById('hero-badge-text');
                if (el) el.textContent = newBadge;
            });
        }
    });
}

function editHeroSubtitle() {
    const currentText = document.getElementById('hero-subtitle')?.textContent.trim() || '';

    if (typeof Swal === 'undefined') {
        const newSubtitle = prompt('Masukkan teks deskripsi baru di bawah judul OSIS:', currentText);
        if (newSubtitle !== null && newSubtitle.trim()) {
            saveHeroConfig({ subtitle: newSubtitle.trim() }, () => {
                const el = document.getElementById('hero-subtitle');
                if (el) el.textContent = newSubtitle.trim();
            });
        }
        return;
    }

    Swal.fire({
        title: '<span style="color:#0f172a; font-weight:800; font-size:1.25rem;">Ubah Teks di Bawah Judul OSIS</span>',
        html: '<p style="color:#64748b; font-size:0.875rem; margin-bottom:1rem;">Teks deskripsi ini menjelaskan peran dan komitmen OSIS di bawah judul SMKN 1 Tarumajaya.</p>',
        input: 'textarea',
        inputValue: currentText,
        inputPlaceholder: 'Tuliskan teks deskripsi OSIS...',
        showCancelButton: true,
        confirmButtonText: 'Simpan Perubahan',
        cancelButtonText: 'Batal',
        confirmButtonColor: '#e11d48',
        cancelButtonColor: '#94a3b8',
        customClass: {
            popup: 'rounded-3xl border border-slate-100 shadow-2xl p-6',
            input: 'rounded-xl border border-slate-200 text-slate-800 text-sm leading-relaxed p-3 min-h-[110px]',
            confirmButton: 'rounded-xl font-bold px-5 py-2.5 shadow-md shadow-rose-200',
            cancelButton: 'rounded-xl font-semibold px-4 py-2.5'
        },
        inputValidator: (value) => {
            if (!value || !value.trim()) {
                return 'Teks deskripsi tidak boleh kosong!';
            }
        }
    }).then((result) => {
        if (result.isConfirmed) {
            const newSubtitle = result.value.trim();
            saveHeroConfig({ subtitle: newSubtitle }, () => {
                const el = document.getElementById('hero-subtitle');
                if (subEl = document.getElementById('hero-subtitle')) {
                    subEl.textContent = newSubtitle;
                }
            });
        }
    });
}

function saveHeroConfig(data, onSuccess) {
    const formData = new FormData();
    for (const key in data) {
        formData.append(key, data[key]);
    }
    formData.append('_token', window.csrfToken || document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '');

    axios.post('/api/site-config/hero', formData)
        .then(response => {
            if (response.data.success) {
                if (onSuccess) onSuccess();
                if (typeof Swal !== 'undefined') {
                    Swal.fire({
                        icon: 'success',
                        title: 'Berhasil',
                        text: response.data.message || 'Perubahan berhasil disimpan!',
                        timer: 1800,
                        showConfirmButton: false,
                        customClass: {
                            popup: 'rounded-3xl border border-slate-100 shadow-2xl'
                        }
                    });
                }
            }
        })
        .catch(error => {
            if (typeof Swal !== 'undefined') {
                Swal.fire({
                    icon: 'error',
                    title: 'Gagal Menyimpan',
                    text: error.response?.data?.error || 'Terjadi kesalahan saat menyimpan data.',
                    confirmButtonColor: '#e11d48',
                    customClass: {
                        popup: 'rounded-3xl border border-slate-100 shadow-2xl'
                    }
                });
            } else {
                alert(error.response?.data?.error || 'Gagal menyimpan perubahan.');
            }
        });
}

function handleContactKeydown(event, id, element) {
    if (event.key === 'Enter') {
        event.preventDefault();
        element.blur();
    }
}

function saveContactValue(id, element) {
    const newValue = element.textContent.trim();
    const oldValue = element.dataset.originalValue || newValue;

    if (newValue === oldValue) return;

    element.dataset.originalValue = newValue;

    axios.put(`/api/site-config/contacts/${id}`, {
        value: newValue,
        _token: window.csrfToken || document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || ''
    })
    .then(response => {
        if (response.data.success) {
            element.style.color = '#10b981';
            setTimeout(() => {
                element.style.color = '';
            }, 1000);
        }
    })
    .catch(error => {
        element.textContent = oldValue;
        element.style.color = '#ef4444';
        setTimeout(() => {
            element.style.color = '';
        }, 1000);
    });
}
